# @lc app=leetcode id=2080 lang=python3
#
# [2080] Range Frequency Queries
#

# @lc code=start
from typing import List
from collections import defaultdict

class RangeFreqQuery:

    def __init__(self, arr: List[int]):
        self.hash = defaultdict(list)

        for index, value in enumerate(arr):
            self.hash[value].append(index)
             
        self.record = defaultdict(int)

    def findFirst(self, arr, target):        
        if arr[0] == target:
            return 0
        
        left, right = 0, len(arr) - 1
        while left < right:            
            mid = left + (right - left) // 2           
            if arr[mid] == target:
                return mid           
            elif arr[mid] < target:
                left = mid + 1                                              
            else:
                right = mid
                                                              
        return left
    
    def findLast(self, arr, target):
        n = len(arr) - 1
        if arr[n] == target:
            return n
        
        left, right = 0, n
        while left < right:            
            mid = left + (right - left + 1) // 2
         
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                left = mid
            else:
                right = mid - 1
                                 
        return left
       
                        
    def query(self, left: int, right: int, value: int) -> int:
        key = left, right, value

        if key in self.record:
            return self.record.get(key)

        arr = self.hash.get(value)      
        print(arr, left, right)

        if arr is None or arr[0] > right or arr[-1] < left:
            return 0
        
        if arr[0] == right or arr[-1] == left:
            return 1    
                        
        first = self.findFirst(arr, left)
        last = self.findLast(arr, right)

        print(first, last)

        res = last - first + 1
        self.record[key] = res

        return res
                        

# Your RangeFreqQuery object will be instantiated and called as such:
# obj = RangeFreqQuery(arr)
# param_1 = obj.query(left,right,value)
# @lc code=end


